25	package hudson.tools;
26	
27	import edu.umd.cs.findbugs.annotations.NonNull;
28	import hudson.Extension;
29	import hudson.FilePath;
30	import hudson.Functions;
31	import hudson.ProxyConfiguration;
32	import hudson.Util;
33	import hudson.model.Node;
34	import hudson.model.TaskListener;
35	import hudson.remoting.VirtualChannel;
36	import hudson.util.FormValidation;
37	import java.io.File;
38	import java.io.IOException;
39	import java.net.HttpURLConnection;
40	import java.net.URI;
41	import java.net.URISyntaxException;
42	import java.net.URL;
43	import java.net.http.HttpClient;
44	import java.net.http.HttpRequest;
45	import java.net.http.HttpResponse;
46	import jenkins.MasterToSlaveFileCallable;
47	import jenkins.model.Jenkins;
48	import org.jenkinsci.Symbol;
49	import org.kohsuke.stapler.DataBoundConstructor;
50	import org.kohsuke.stapler.QueryParameter;
51	import org.kohsuke.stapler.interceptor.RequirePOST;
52	
53	/**
54	 * Installs a tool into the Hudson working area by downloading and unpacking a ZIP file.
55	 * @since 1.305
56	 */
57	public class ZipExtractionInstaller extends ToolInstaller {
58	
59	    /**
60	     * URL of a ZIP file which should be downloaded in case the tool is missing.
61	     */
62	    private final String url;
63	    /**
64	     * Optional subdir to extract.
65	     */
66	    private final String subdir;
67	
68	    @DataBoundConstructor
69	    public ZipExtractionInstaller(String label, String url, String subdir) {
70	        super(label);
71	        this.url = url;
72	        this.subdir = Util.fixEmptyAndTrim(subdir);
73	    }
74	
75	    public String getUrl() {
76	        return url;
77	    }
78	
79	    public String getSubdir() {
80	        return subdir;
81	    }
82	
83	    @Override
84	    public FilePath performInstallation(ToolInstallation tool, Node node, TaskListener log) throws IOException, InterruptedException {
85	        FilePath dir = preferredLocation(tool, node);
86	        if (dir.installIfNecessaryFrom(new URL(url), log, "Unpacking " + url + " to " + dir + " on " + node.getDisplayName())) {
87	            dir.act(new ChmodRecAPlusX());
88	        }
89	        if (subdir == null) {
90	            return dir;
91	        } else {
92	            return dir.child(subdir);
93	        }
94	    }
95	
96	    @Extension @Symbol("zip")
97	    public static class DescriptorImpl extends ToolInstallerDescriptor<ZipExtractionInstaller> {
98	
99	        @NonNull
100	        @Override
101	        public String getDisplayName() {
102	            return Messages.ZipExtractionInstaller_DescriptorImpl_displayName();
103	        }
104	
105	        @RequirePOST
106	        public FormValidation doCheckUrl(@QueryParameter String value) throws InterruptedException {
107	            Jenkins.get().checkPermission(Jenkins.ADMINISTER);
108	
109	            value = Util.fixEmptyAndTrim(value);
110	            if (value == null) {
111	                return FormValidation.ok();
112	            }
113	
114	            URI uri;
115	            try {
116	                uri = new URI(value);
117	            } catch (URISyntaxException e) {
118	                return FormValidation.error(e, Messages.ZipExtractionInstaller_malformed_url());
119	            }
120	            HttpClient httpClient = ProxyConfiguration.newHttpClient();
121	            HttpRequest httpRequest;
122	            try {
123	                httpRequest = ProxyConfiguration.newHttpRequestBuilder(uri)
124	                        .method("HEAD", HttpRequest.BodyPublishers.noBody())
125	                        .build();
126	            } catch (IllegalArgumentException e) {
127	                return FormValidation.error(e, Messages.ZipExtractionInstaller_malformed_url());
128	            }
129	            try {
130	                HttpResponse<Void> httpResponse = httpClient.send(httpRequest, HttpResponse.BodyHandlers.discarding());
131	                if (httpResponse.statusCode() == HttpURLConnection.HTTP_OK) {
132	                    return FormValidation.ok();
133	                }
134	                return FormValidation.error(Messages.ZipExtractionInstaller_bad_connection());
135	            } catch (IOException e) {
136	                return FormValidation.error(e, Messages.ZipExtractionInstaller_could_not_connect());
137	            }
138	        }
139	
140	    }
141	
142	    /**
143	     * Sets execute permission on all files, since unzip etc. might not do this.
144	     * Hackish, is there a better way?
145	     */
146	    static class ChmodRecAPlusX extends MasterToSlaveFileCallable<Void> {
147	        private static final long serialVersionUID = 1L;
148	
149	        @Override
150	        public Void invoke(File d, VirtualChannel channel) throws IOException {
151	            if (!Functions.isWindows())
152	                process(d);
153	            return null;
154	        }
155	
156	        private void process(File f) {
157	            if (f.isFile()) {
158	                f.setExecutable(true, false);
159	            } else {
160	                File[] kids = f.listFiles();
161	                if (kids != null) {
162	                    for (File kid : kids) {
163	                        process(kid);
164	                    }
165	                }
166	            }
167	        }
168	    }
169	
170	}
